INSERT INTO reviewed_module VALUES ('small-boats','2026-09-17','{"reviewed_at":"2026-09-17","refresh":"Manual snapshot; latest chart period ends 30 June 2026","sources":{"trend":{"title":"Small boat arrivals: year ending June 2026","url":"https://www.gov.uk/government/statistics/immigration-system-statistics-year-ending-june-2026/how-many-people-come-to-the-uk-via-illegal-entry-routes","date":"2026-08-27","locator":"Sections 2.1–2.2; IER_02a"},"annual":{"title":"Small boat arrivals: calendar year 2025","url":"https://www.gov.uk/government/statistics/immigration-system-statistics-year-ending-december-2025/how-many-people-come-to-the-uk-via-illegal-entry-routes","date":"2026-02-26","locator":"Section 2.1"},"nca":{"title":"National Strategic Assessment 2026: border","publisher":"National Crime Agency","url":"https://www.nationalcrimeagency.gov.uk/nsa-domains-2026/nsa-soc-at-the-border-2026","date":null,"locator":"The Sea Border — Small Boats"},"daily":{"title":"Daily and weekly Channel activity","url":"https://www.gov.uk/government/publications/migrants-detected-crossing-the-english-channel-in-small-boats","date":"2026-09-17","locator":"Documents and Details"},"processing":{"title":"Initial processing: Home Office factsheet","url":"https://www.gov.uk/government/publications/manston-arrivals-and-processing-centre/manston-factsheet","date":"2026-02-25","locator":"Initial processing and immediate healthcare"},"screening":{"title":"Claim asylum: screening","url":"https://www.gov.uk/claim-asylum/screening","date":null,"locator":"Attend an asylum screening"},"routing":{"title":"Claim asylum: after screening","url":"https://www.gov.uk/claim-asylum/after-your-screening","date":null,"locator":"Consideration in the UK; detention; caseworkers"},"support":{"title":"Asylum support","url":"https://www.gov.uk/asylum-support","date":null,"locator":"Overview and eligibility"},"interview":{"title":"Claim asylum: interview","url":"https://www.gov.uk/claim-asylum/asylum-interview","date":null,"locator":"Evidence and what happens in the interview"},"decision":{"title":"Claim asylum: decision and next steps","url":"https://www.gov.uk/claim-asylum/decision","date":null,"locator":"Successful claim; no reason to stay"},"france":{"title":"UK–France agreement: transfers and returns","url":"https://www.gov.uk/government/publications/the-border-security-commanders-annual-report-data/transfers-into-and-returns-from-the-united-kingdom-under-the-uk-france-agreement-on-the-prevention-of-dangerous-journeys-between-6-august-2025-and-30","date":null,"locator":"6 August 2025–30 June 2026"}},"comparisons":{"rolling":{"title":"Latest quarterly release · years ending June","unit":"people","rows":[["July 2023–June 2024",31493],["July 2024–June 2025",43309],["July 2025–June 2026",33374]],"source":"trend","notes":"Complete 12-month periods with the same seasonal coverage. This is not the January–June 2026 total.","published":"27 August 2026"},"calendar":{"title":"Complete calendar years · 2024 and 2025","unit":"people","rows":[["January–December 2024",36816],["January–December 2025",41472]],"source":"nca","notes":"Two complete calendar years. This increase and the later rolling-year decrease describe different periods.","published":"2026 assessment; exact date not recorded"}},"stages":[{"title":"Arrival & initial processing","body":"People brought to the UK enter initial processing. Officials collect and verify identity and other details, with immediate healthcare needs addressed. Initial processing is distinct from the later decision on an asylum claim.","sources":["processing"]},{"title":"Register an asylum claim","body":"A person seeking protection tells an immigration officer. Screening records identity, photographs and fingerprints, the reason for claiming, and relevant medical information. An interpreter can be requested. Registration does not itself grant refugee status.","sources":["screening"]},{"title":"Decide where the claim is considered","body":"The Home Office considers whether to examine the claim in the UK. A safe-third-country connection may trigger an inadmissibility process. Transfer depends on applicable arrangements and the individual case; arrival from France does not mean every person is automatically returned.","sources":["routing","france"]},{"title":"While the case is pending","body":"Eligible people who cannot support themselves may receive accommodation and financial support. Reporting requirements can apply. Some people may be detained; others are not. Children and people with particular vulnerabilities require different consideration.","sources":["support","routing"]},{"title":"Evidence & asylum interview","body":"Where the claim is examined, the applicant explains why they fear return and supplies supporting evidence. A substantive interview explores the protection claim in more detail than screening. Interpretation is available where needed.","sources":["interview"]},{"title":"Decision on protection","body":"A successful claim can lead to refugee status or humanitarian protection; other permission is possible. The length and conditions of permission depend on the applicable rules and claim date. Recognition is not automatic citizenship or permanent settlement.","sources":["decision"]},{"title":"Appeal or departure","body":"A refusal may carry a right of appeal. If there is no remaining permission or legal basis to stay after the relevant process, departure may be voluntary or enforced. A refusal, an appeal outcome and an actual return are separate events.","sources":["decision"]}]}');
